result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": """"Tiny GraphQL server: Ariadne + Flask + SQLite."""
import os
import sqlite3

from ariadne import ObjectType, graphql_sync, make_executable_schema
from flask import Flask, jsonify, request

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "library.db")

SDL = """
type Author {
  id: ID!
  name: String!
  books: [Book!]!
}

type Book {
  id: ID!
  title: String!
  year: Int!
  authorId: ID!
}

type Query {
  books(yearFrom: Int): [Book!]!
  author(id: ID!): Author
}

type Mutation {
  addBook(authorId: ID!, title: String!, year: Int!): Book!
}
"""


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as db:
        db.executescript(
            """
            CREATE TABLE IF NOT EXISTS authors (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS books (
                id INTEGER PRIMARY KEY,
                author_id INTEGER NOT NULL REFERENCES authors(id),
                title TEXT NOT NULL,
                year INTEGER NOT NULL
            );
            """
        )
        count = db.execute("SELECT COUNT(*) FROM authors").fetchone()[0]
        if count == 0:
            seed_authors = [
                (1, "Ursula K. Le Guin"),
                (2, "George Orwell"),
                (3, "Italo Calvino"),
            ]
            seed_books = [
                (1, 1, "A Wizard of Earthsea", 1968),
                (2, 1, "The Left Hand of Darkness", 1969),
                (3, 1, "The Dispossessed", 1974),
                (4, 2, "Nineteen Eighty-Four", 1949),
                (5, 2, "Animal Farm", 1945),
                (6, 3, "Invisible Cities", 1972),
                (7, 3, "If on a winter's night a traveler", 1979),
                (8, 3, "The Baron in the Trees", 1957),
            ]
            db.executemany("INSERT INTO authors VALUES (?, ?)", seed_authors)
            db.executemany("INSERT INTO books VALUES (?, ?, ?, ?)", seed_books)


def book_row_to_dict(row):
    return {"id": row["id"], "title": row["title"], "year": row["year"], "authorId": row["author_id"]}


query = ObjectType("Query")
mutation = ObjectType("Mutation")


@query.field("books")
def resolve_books(_, info, yearFrom=None):
    with get_db() as db:
        if yearFrom is None:
            rows = db.execute("SELECT * FROM books ORDER BY id").fetchall()
        else:
            rows = db.execute(
                "SELECT * FROM books WHERE year >= ? ORDER BY id", (yearFrom,)
            ).fetchall()
    return [book_row_to_dict(r) for r in rows]


@query.field("author")
def resolve_author(_, info, id):
    with get_db() as db:
        row = db.execute("SELECT * FROM authors WHERE id = ?", (int(id),)).fetchone()
    return dict(row) if row else None


@mutation.field("addBook")
def resolve_add_book(_, info, authorId, title, year):
    # Domain validation -> surfaced as a GraphQL error (HTTP 200), not a 500.
    if year < 1450:
        from graphql import GraphQLError

        raise GraphQLError(
            f"Invalid year {year}: books must be printed after the invention of "
            "the printing press (1450).",
            extensions={"code": "BAD_YEAR", "year": year},
        )
    with get_db() as db:
        author = db.execute("SELECT id FROM authors WHERE id = ?", (int(authorId),)).fetchone()
        if author is None:
            from graphql import GraphQLError

            raise GraphQLError(
                f"Author {authorId} does not exist.",
                extensions={"code": "AUTHOR_NOT_FOUND"},
            )
        cur = db.execute(
            "INSERT INTO books (author_id, title, year) VALUES (?, ?, ?)",
            (int(authorId), title, year),
        )
        new_id = cur.lastrowid
        row = db.execute("SELECT * FROM books WHERE id = ?", (new_id,)).fetchone()
    return book_row_to_dict(row)


schema = make_executable_schema(SDL, query, mutation)

app = Flask(__name__)


@app.post("/graphql")
def graphql_endpoint():
    payload = request.get_json(force=True)
    _, result = graphql_sync(schema, payload, context_value={"request": request})
    status = 200 if ("errors" not in result or result["errors"]) is not None else 400
    # GraphQL errors are reported in-band; keep HTTP 200 per GraphQL-over-HTTP convention.
    return jsonify(result), 200


@app.errorhandler(404)
def not_found(_):
    return jsonify({"error": "not found"}), 404


if __name__ == "__main__":
    init_db()
    app.run(port=5030, debug=True)
"})
print(result)

