import pytest

from app import app as flask_app, get_db


@pytest.fixture()
def client():
    flask_app.config["TESTING"] = True
    with flask_app.test_client() as client:
        yield client


def gql(client, query, variables=None):
    resp = client.post("/graphql", json={"query": query, "variables": variables or {}})
    assert resp.status_code == 200
    return resp.get_json()


def test_nested_author_books(client):
    result = gql(
        client,
        """
        query {
          author(id: 1) {
            id
            name
            books {
              title
              year
            }
          }
        }
        """,
    )
    assert "errors" not in result
    author = result["data"]["author"]
    assert author["name"] == "Ursula K. Le Guin"
    titles = [b["title"] for b in author["books"]]
    assert "A Wizard of Earthsea" in titles
    assert all(isinstance(b["year"], int) for b in author["books"])


def test_books_filtered_by_year(client):
    result = gql(
        client,
        """
        query {
          books(yearFrom: 1970) {
            title
            year
          }
        }
        """,
    )
    assert "errors" not in result
    books = result["data"]["books"]
    assert len(books) >= 1
    assert all(b["year"] >= 1970 for b in books)
    titles = [b["title"] for b in books]
    assert "The Dispossessed" in titles  # 1974
    assert "Animal Farm" not in titles  # 1945 filtered out

    # No filter -> everything
    result = gql(client, "{ books { id } }")
    assert len(result["data"]["books"]) == 8


def test_mutation_add_book_then_visible_in_query(client):
    mutation_result = gql(
        client,
        """
        mutation {
          addBook(authorId: 2, title: "Coming Up for Air", year: 1939) {
            id
            title
            year
            authorId
          }
        }
        """,
    )
    # NOTE: 1939 < 1450? No — it's fine. But wait, this is a valid year.
    assert "errors" not in mutation_result
    book = mutation_result["data"]["addBook"]
    assert book["title"] == "Coming Up for Air"
    assert book["authorId"] == "2"
    new_id = book["id"]

    follow_up = gql(
        client,
        """
        query($id: ID!) {
          author(id: $id) {
            name
            books { id title }
          }
        }
        """,
        {"id": "2"},
    )
    books = follow_up["data"]["author"]["books"]
    assert new_id in [b["id"] for b in books]
    assert "Coming Up for Air" in [b["title"] for b in books]

    # cleanup so the seed-count assertion elsewhere stays deterministic
    with get_db() as db:
        db.execute("DELETE FROM books WHERE id = ?", (new_id,))


def test_invalid_year_is_graphql_error_not_500(client):
    before = gql(client, "{ books { id } }")
    count_before = len(before["data"]["books"])

    result = gql(
        client,
        """
        mutation {
          addBook(authorId: 3, title: "Fake Medieval Codex", year: 1230) {
            id
          }
        }
        """,
    )
    # HTTP 200 with the error in-band (not a transport-level failure)
    resp = client.post(
        "/graphql",
        json={
            "query": 'mutation { addBook(authorId: 3, title: "X", year: 1230) { id } }'
        },
    )
    assert resp.status_code == 200

    errors = result.get("errors")
    assert errors, "expected a GraphQL error entry"
    assert errors[0]["extensions"]["code"] == "BAD_YEAR"
    assert "1450" in errors[0]["message"]
    assert result["data"] is None

    after = gql(client, "{ books { id } }")
    assert len(after["data"]["books"]) == count_before  # nothing was written
"})
print(result)

